# CELL 6: BUILT-IN VALIDATION SUITE   (Eir 2.0.15)
# =============================================================================
# Reference structures with analytically known answers, generated on the fly.
#
# The point is to test the machinery - CIF parsing, symmetry expansion,
# neighbour finding, coordination assignment, the bond valence sum, the GII
# formula, occupancy weighting - independently of whether any particular R0 or
# b is the right one.
#
# The tests are therefore SELF-CALIBRATING. Rather than hardcoding a lattice
# parameter and asserting a GII, each test reads the parameters Eir will
# actually use, solves for the lattice parameter that must give the target, and
# then checks that Eir returns it. A test that hardcoded numbers would break
# every time the parameter file was updated, and would be testing the
# parameters rather than the code.
#
# Run VALIDATE() after any change to the analysis path.

import contextlib
import io
import math
import os
import tempfile

# Rocksalt, Fm-3m. One cation site, one anion site, both octahedral, and the
# cation-anion distance is exactly a/2. Everything about it is known by hand.
_ROCKSALT_CIF = """data_eir_validation
_cell_length_a {a:.6f}
_cell_length_b {a:.6f}
_cell_length_c {a:.6f}
_cell_angle_alpha 90.
_cell_angle_beta 90.
_cell_angle_gamma 90.
_space_group_IT_number 225
_symmetry_space_group_name_H-M 'F m -3 m'
loop_
_atom_site_label
_atom_site_type_symbol
_atom_site_symmetry_multiplicity
_atom_site_Wyckoff_symbol
_atom_site_fract_x
_atom_site_fract_y
_atom_site_fract_z
_atom_site_B_iso_or_equiv
_atom_site_occupancy
{cat}1 {cat}{cv}+ 4 a 0. 0. 0. 0.5 1.
O1 O2- 4 b 0.5 0.5 0.5 0.5 {oocc:.4f}
"""

# The same structure as ICSD writes it when the depositor leaves the oxidation
# state unset: an _atom_type_oxidation_number loop of zeros, and type symbols
# reading "M0+" and "O0-". ICSD 206948 (NaCl) and 616052 (BaS) are real
# examples. Taking those zeros literally makes the bond valence sum look up
# parameters for M(0+), find none, and return no result at all - no bond
# length, no radius, no sum - for a structure that is otherwise unremarkable.
# On the 613-structure rock salt survey this silently removed 73 sites in 40
# ordinary compounds, which is enough to move a published validation rate.
_ROCKSALT_ZERO_VALENCE_CIF = """data_eir_validation_zero
_cell_length_a {a:.6f}
_cell_length_b {a:.6f}
_cell_length_c {a:.6f}
_cell_angle_alpha 90.
_cell_angle_beta 90.
_cell_angle_gamma 90.
_space_group_IT_number 225
_symmetry_space_group_name_H-M 'F m -3 m'
loop_
_atom_type_symbol
_atom_type_oxidation_number
{cat}0+ 0
O0+ 0
loop_
_atom_site_label
_atom_site_type_symbol
_atom_site_symmetry_multiplicity
_atom_site_Wyckoff_symbol
_atom_site_fract_x
_atom_site_fract_y
_atom_site_fract_z
_atom_site_B_iso_or_equiv
_atom_site_occupancy
{cat}1 {cat}0+ 4 a 0. 0. 0. 0.5 1.
O1 O0+ 4 b 0.5 0.5 0.5 0.5 1.
"""

import gemmi

VALIDATION_CATION = 'Mg'
VALIDATION_VALENCE = 2


def _lattice_for_bvs(target_bvs, R0, b, cn=6):
    """Cubic a that puts a rocksalt cation at exactly `target_bvs` v.u."""
    return 2.0 * (R0 - b * math.log(target_bvs / cn))


def _run_cif(text):
    """
    Write a CIF to a temporary file, analyse it, return the results dict.

    process_single_cif is deliberately chatty, which is right when you are
    inspecting one structure and wrong here, so its output is swallowed. If a
    test fails and you want to see why, call process_single_cif yourself on the
    same CIF text.
    """
    global PY3DMOL_AVAILABLE
    d = tempfile.mkdtemp()
    p = os.path.join(d, 'eir_validation.cif')
    # Several reference structures deviate by more than 0.30 v.u. by design,
    # which is exactly the condition that triggers a 3D view. Those render
    # through IPython's display machinery rather than stdout, so redirecting
    # stdout alone does not stop them and the test output fills with
    # <py3Dmol.view ...> objects. Turn the viewer off for the duration.
    _viz_was = globals().get('PY3DMOL_AVAILABLE', False)
    try:
        PY3DMOL_AVAILABLE = False
        with open(p, 'w', encoding='utf-8') as f:
            f.write(text)
        with contextlib.redirect_stdout(io.StringIO()):
            return process_single_cif(p)
    finally:
        PY3DMOL_AVAILABLE = _viz_was
        try:
            os.unlink(p)
            os.rmdir(d)
        except OSError:
            pass


def VALIDATE(verbose=True, tol_gii=0.002, tol_len=0.001):
    """
    Run the built-in reference tests. Returns True if all pass.

    Each test states what it is checking and why, so a failure points at the
    part of the pipeline that broke rather than just reporting a number.
    """
    cat, cv = VALIDATION_CATION, VALIDATION_VALENCE
    results = []

    def report(name, ok, detail):
        results.append(ok)
        if verbose:
            print(f"  {'PASS' if ok else 'FAIL'}  {name}")
            print(f"        {detail}")

    R0, b = db_manager.get_bv_parameters(cat, cv, 'O')
    if R0 is None:
        print(f"  Cannot validate: no bond valence parameters for "
              f"{cat}{cv}+-O in the database.")
        return False

    if verbose:
        print("=" * 70)
        print("EIR VALIDATION SUITE")
        print("=" * 70)
        print(f"  Reference structure : rocksalt {cat}O, Fm-3m")
        print(f"  Parameters in use   : R0 = {R0}, b = {b}")
        print(f"  Targets are solved from those parameters, so this tests the")
        print(f"  code and not the parameter values.")
        print()

    # -- 1. geometry and coordination, no parameters involved ----------------
    a = 4.20
    r = _run_cif(_ROCKSALT_CIF.format(a=a, cat=cat, cv=cv, oocc=1.0))
    if not r.get('success'):
        report("1. geometry and coordination", False,
               f"analysis failed: {r.get('error')}")
        # Deliberate early exit: every test below reads geometry, so running
        # them after this one fails produces ten more failures that all say
        # the same thing.
        raise AssertionError(
            "Eir validation stopped at test 1: the reference rocksalt could "
            f"not be analysed ({r.get('error')}). Nothing below it can be "
            "meaningful.")
    site = next((s for s in r['sites'] if s.get('element') == cat), None)
    ok = (site is not None and site.get('cn') == 6
          and abs(site.get('avg_bond_length', 0) - a / 2) < tol_len)
    report("1. geometry and coordination",
           ok,
           f"a = {a}, so every {cat}-O bond must be exactly {a/2:.4f} A with CN 6. "
           f"Got CN {site.get('cn') if site else None}, "
           f"d = {site.get('avg_bond_length') if site else None}")

    # -- 2-4. GII at known values -------------------------------------------
    for target in (0.000, 0.200, 0.400):
        a = _lattice_for_bvs(cv + target, R0, b)
        r = _run_cif(_ROCKSALT_CIF.format(a=a, cat=cat, cv=cv, oocc=1.0))
        if not r.get('success'):
            report(f"{len(results)+1}. GII = {target:.3f}", False,
                   f"analysis failed: {r.get('error')}")
            continue
        got = r.get('gii')
        ok = got is not None and abs(got - target) < tol_gii
        report(f"{len(results)+1}. GII = {target:.3f}",
               ok,
               f"a = {a:.5f} A puts the cation at {cv + target:.3f} v.u., so GII "
               f"must be {target:.3f}. Got {got:.5f}" if got is not None
               else "no GII returned")

    # -- 5. GII is the RMS form, not the old normalised mean ----------------
    target = 0.400
    a = _lattice_for_bvs(cv + target, R0, b)
    r = _run_cif(_ROCKSALT_CIF.format(a=a, cat=cat, cv=cv, oocc=1.0))
    gii, legacy = r.get('gii'), r.get('bvs_discrepancy')
    ok = (gii is not None and legacy is not None
          and abs(gii - target) < tol_gii
          and abs(legacy - target / cv) < tol_gii)
    report("5. GII uses the published RMS definition",
           ok,
           f"one site off by {target:.3f} v.u. on a formal valence of {cv}: the "
           f"RMS form gives {target:.3f}, the older normalised form gives "
           f"{target/cv:.3f}. Got gii={gii}, bvs_discrepancy={legacy}")

    # -- 6. the sum rule ----------------------------------------------------
    # Every bond contributes once to a cation sum and once to an anion sum, so
    # the totals must agree. This checks that the cation and anion engines see
    # the same bonds. In rocksalt both sites have multiplicity 4.
    a = _lattice_for_bvs(cv, R0, b)
    r = _run_cif(_ROCKSALT_CIF.format(a=a, cat=cat, cv=cv, oocc=1.0))
    site = next((s for s in r['sites'] if s.get('element') == cat), None)
    anion = (r.get('anion_summary') or {}).get('anion_bvs_mean')
    ok = (site is not None and anion is not None
          and abs(site['bvs'] - anion) < 0.005)
    report("6. cation and anion sums agree",
           ok,
           f"equal multiplicities, so the cation total must equal the anion "
           f"total. Cation {site['bvs'] if site else None}, "
           f"anion {anion}")

    # -- 7. occupancy weighting --------------------------------------------
    # Halving the anion occupancy must halve the bond valence sum. This is the
    # A8 behaviour and it is exact, not approximate.
    a = _lattice_for_bvs(cv, R0, b)
    full = _run_cif(_ROCKSALT_CIF.format(a=a, cat=cat, cv=cv, oocc=1.0))
    half = _run_cif(_ROCKSALT_CIF.format(a=a, cat=cat, cv=cv, oocc=0.5))
    sf = next((s for s in full['sites'] if s.get('element') == cat), None)
    sh = next((s for s in half['sites'] if s.get('element') == cat), None)
    ok = (sf and sh and sf.get('bvs') and sh.get('bvs')
          and abs(sh['bvs'] - 0.5 * sf['bvs']) < 0.005)
    report("7. occupancy weighting is exact",
           ok,
           f"halving the O occupancy must halve the sum. Full {sf.get('bvs') if sf else None}, "
           f"half {sh.get('bvs') if sh else None}, "
           f"expected {0.5*sf['bvs']:.4f}" if sf and sf.get('bvs') else "no result")

    # -- 8. GII is the RMS of the per-site deviations -----------------------
    # Recompute GII from the sites Eir itself reported. This catches a GII that
    # has drifted away from the sites it is supposed to summarise.
    a = _lattice_for_bvs(cv + 0.35, R0, b)
    r = _run_cif(_ROCKSALT_CIF.format(a=a, cat=cat, cv=cv, oocc=1.0))
    devs = [s['bvs'] - abs(s['valence'])
            for s in r.get('sites', [])
            if s.get('bvs') is not None and s.get('valence')]
    recomputed = math.sqrt(sum(d * d for d in devs) / len(devs)) if devs else None
    ok = (recomputed is not None and r.get('gii') is not None
          and abs(recomputed - r['gii']) < 0.002)
    report("8. GII matches its own per-site output",
           ok,
           f"RMS of the reported deviations = {recomputed:.5f}, "
           f"reported GII = {r.get('gii')}" if recomputed is not None
           else "no sites returned")

    # -- 9. the candidate search radius is wide enough ----------------------
    # The first shell in a compact rocksalt sits at ~2.1 A, well inside any
    # plausible cutoff, so tests 1-8 pass even with a badly truncated search.
    # This one puts the bonds at 3.8 A deliberately. The lattice is
    # unphysically large, which does not matter: the point is to check that
    # the neighbour search reaches far enough to find a real coordination
    # shell. A cutoff of 3.5 A - the value that was wrong for 122 sites in the
    # layered-oxide survey - fails here.
    a_wide = 7.60
    r = _run_cif(_ROCKSALT_CIF.format(a=a_wide, cat=cat, cv=cv, oocc=1.0))
    site = (next((s for s in r.get('sites', []) if s.get('element') == cat), None)
            if r.get('success') else None)
    ok = site is not None and site.get('cn') == 6
    report("9. neighbour search reaches a distant shell",
           ok,
           f"a = {a_wide} puts every {cat}-O bond at {a_wide/2:.2f} A. CN must "
           f"still be 6. Got "
           f"{site.get('cn') if site else 'no ' + cat + ' site returned'}")

    # -- 10. a stated valence of zero must not be believed -----------------
    # This is a regression guard, not a property of bond valence theory. It
    # exists because a correct fix - letting per-atom CIF valences reach the
    # calculation - had the side effect of believing the zeros, and that
    # stopped Eir reproducing its own published rock salt analysis. The
    # failure was silent: coordination numbers still appeared, so nothing
    # looked wrong until the validation rate was compared against the paper.
    a = _lattice_for_bvs(cv, R0, b)
    r = _run_cif(_ROCKSALT_ZERO_VALENCE_CIF.format(a=a, cat=cat))
    site = (next((s for s in r.get('sites', []) if s.get('element') == cat), None)
            if r.get('success') else None)
    ok = (site is not None
          and site.get('valence') not in (None, 0, 0.0)
          and site.get('bvs') is not None)
    report("10. a CIF valence of zero is not taken literally",
           ok,
           f"the CIF declares {cat}0+ and O0+, which is how ICSD writes an "
           f"unset oxidation state. The valence must fall back to the "
           f"database, not stay at zero. Got valence="
           f"{site.get('valence') if site else None}, "
           f"bvs={site.get('bvs') if site else None}, "
           f"source={site.get('valence_source') if site else None}")

    # -- 11. the same thing by the route the BATCH actually takes -----------
    # Test 10 calls process_single_cif directly, with no oxidation-state
    # argument. batch_process_directory does something different: it reads the
    # CIF's own oxidation-state loop and passes it in as an override, which
    # outranks the database fallback. A file declaring zeros therefore reaches
    # the calculation as a user override of zero.
    #
    # This distinction is not academic. Test 10 passed for a full round while
    # every batch run still returned no bond valence sums at all, because the
    # two paths supply different inputs to the same function. A test that only
    # exercises the convenient path is not testing what anyone runs.
    _zero_cif = _ROCKSALT_ZERO_VALENCE_CIF.format(a=a, cat=cat)
    _d = tempfile.mkdtemp()
    _p = os.path.join(_d, 'eir_validation_batchpath.cif')
    try:
        with open(_p, 'w', encoding='utf-8') as _f:
            _f.write(_zero_cif)
        _viz_was = globals().get('PY3DMOL_AVAILABLE', False)
        try:
            PY3DMOL_AVAILABLE = False
            with contextlib.redirect_stdout(io.StringIO()):
                _ox, _src, _t7 = get_oxidation_states_for_analysis(_p, '', None)
                r2 = process_single_cif(_p, _ox)
        finally:
            PY3DMOL_AVAILABLE = _viz_was
    finally:
        try:
            os.unlink(_p)
            os.rmdir(_d)
        except OSError:
            pass

    site2 = (next((s for s in r2.get('sites', []) if s.get('element') == cat), None)
             if r2.get('success') else None)
    ok = (site2 is not None
          and site2.get('valence') not in (None, 0, 0.0)
          and site2.get('bvs') is not None)
    report("11. the same, via the batch's oxidation-state override",
           ok,
           f"batch_process_directory passes the CIF's own states in as an "
           f"override; here that is {_ox}. A zero override must not outrank "
           f"the database either. Got valence="
           f"{site2.get('valence') if site2 else None}, "
           f"bvs={site2.get('bvs') if site2 else None}")

    # -- 12. the coordination shell rules ------------------------------------
    # VALIDATE_SHELL has existed since v2.0.3 and nothing called it. That is
    # how bv_shell_cn and econ_weighted_bvs came to be deleted as a side
    # effect of inserting the adaptive shell beside them: syntax valid, no
    # name duplicated, and the only test that exercised them never ran.
    try:
        _shell_ok = VALIDATE_SHELL(verbose=False)
        _shell_detail = 'the shell cases in CELL 1'
    except Exception as _e:
        _shell_ok = False
        _shell_detail = f'{type(_e).__name__}: {_e}'
    report('12. coordination shell rules', bool(_shell_ok), _shell_detail)

    # -- 13. normaliser translations are derived, not assumed ----------------
    # The seven half-lattice vectors were hard-coded until v2.0.6. They are
    # the normaliser translations of Pnma and of nothing else: for Fd-3m the
    # cubic rotations forbid them, which is why the shift screen fired zero
    # times on 472 pyrochlores.
    _pnma = set(normaliser_translations(
        gemmi.find_spacegroup_by_name('P n m a')))
    _seven = {(0.5, 0, 0), (0, 0.5, 0), (0, 0, 0.5), (0.5, 0.5, 0),
              (0.5, 0, 0.5), (0, 0.5, 0.5), (0.5, 0.5, 0.5)}
    _fd3m = normaliser_translations(
        gemmi.find_spacegroup_by_name('F d -3 m'))
    _p1 = normaliser_translations(gemmi.find_spacegroup_by_name('P 1'))
    report('13. normaliser translations',
           _pnma == _seven and _fd3m == [(0.5, 0.5, 0.5)] and _p1 == [],
           f'Pnma must give the seven half-lattice vectors (got {len(_pnma)}), '
           f'Fd-3m only (1/2,1/2,1/2) (got {_fd3m}), and P1 none because it '
           f'admits every translation (got {len(_p1)})')

    # -- 14. the origin-choice offset is derived from the two settings -------
    _off = origin_choice_offset(gemmi.find_spacegroup_by_name('F d -3 m'))
    _none = origin_choice_offset(gemmi.find_spacegroup_by_name('P n m a'))
    report('14. origin-choice offset',
           _off is not None and all(abs(x - 0.375) < 1e-9 for x in _off)
           and _none is None,
           f'Fd-3m has two origins offset by (3/8,3/8,3/8) (got {_off}); '
           f'Pnma has one, so None (got {_none})')

    # -- 15. the two packing floors fire on an impossible cell ---------------
    # Rocksalt at a = 4.20 has anion-anion and cation-cation contacts of
    # a/sqrt(2) = 2.970 A, above both floors. Compressed to a = 3.00 they
    # fall to 2.121 A, below both. Neither floor looks outward from a cation,
    # so this is the one pair of screens a bond valence sum cannot stand in
    # for: ICSD 85235 has a GII of 0.0047 and two oxygens 2.191 A apart.
    _r_ok = _run_cif(_ROCKSALT_CIF.format(a=4.20, cat=cat, cv=cv, oocc=1.0))
    _r_bad = _run_cif(_ROCKSALT_CIF.format(a=3.00, cat=cat, cv=cv, oocc=1.0))
    _ok_aa, _ok_cc = (_r_ok.get('anion_packing_plausible'),
                      _r_ok.get('cation_packing_plausible'))
    _bad_aa, _bad_cc = (_r_bad.get('anion_packing_plausible'),
                        _r_bad.get('cation_packing_plausible'))
    report('15. anion and cation packing floors',
           _ok_aa is True and _ok_cc is True
           and _bad_aa is False and _bad_cc is False,
           f'at a = 4.20 both contacts are 2.970 A and must pass '
           f'(anion {_ok_aa}, cation {_ok_cc}); at a = 3.00 both are '
           f'2.121 A and must fail (anion {_bad_aa}, cation {_bad_cc})')

    # -- 16. measured bond lengths resolve and name their source -------------
    _bl = expected_bond_length(cat, cv, 6, 'O')
    _li = expected_bond_length('Li', 1, 4, 'O')
    report('16. measured bond lengths',
           _bl is not None and _li is not None
           and _li.get('tier') == 1 and _li.get('min') is not None,
           f"{cat}({cv}+) at CN 6 must resolve (source "
           f"{_bl.get('source') if _bl else None}); Li(1+) at CN 4 must be "
           f"tier 1 with a usable floor (tier {_li.get('tier') if _li else None}, "
           f"min {_li.get('min') if _li else None})")
    # -- 17 to 19. a CIF valence with no parameter key of its own ----------
    # v2.0.43 regression guard. 2.0.42 checked parameters at the CIF's exact
    # valence and silently removed any cation that missed: 17 fluorites failed
    # outright and 56 more were judged on the other species of a shared site.
    # All three go by the batch route, because that is the one that passes the
    # CIF's own valences in.
    def _batch_route(text, name):
        global PY3DMOL_AVAILABLE
        _d = tempfile.mkdtemp()
        _p = os.path.join(_d, name)
        _viz = globals().get('PY3DMOL_AVAILABLE', False)
        try:
            with open(_p, 'w', encoding='utf-8') as _f:
                _f.write(text)
            PY3DMOL_AVAILABLE = False
            with contextlib.redirect_stdout(io.StringIO()):
                _ox, _s, _t = get_oxidation_states_for_analysis(_p, '', None)
                return process_single_cif(_p, _ox)
        finally:
            PY3DMOL_AVAILABLE = _viz
            try:
                os.unlink(_p)
                os.rmdir(_d)
            except OSError:
                pass

    def _fluorite(a, types, sites):
        return ("data_eir_validation_fluorite\n"
                f"_cell_length_a {a:.4f}\n_cell_length_b {a:.4f}\n"
                f"_cell_length_c {a:.4f}\n_cell_angle_alpha 90.\n"
                "_cell_angle_beta 90.\n_cell_angle_gamma 90.\n"
                "_space_group_IT_number 225\n"
                "_symmetry_space_group_name_H-M 'F m -3 m'\n"
                "loop_\n_atom_type_symbol\n_atom_type_oxidation_number\n"
                + ''.join(f"{t} {v}\n" for t, v in types)
                + "loop_\n_atom_site_label\n_atom_site_type_symbol\n"
                "_atom_site_symmetry_multiplicity\n_atom_site_Wyckoff_symbol\n"
                "_atom_site_fract_x\n_atom_site_fract_y\n_atom_site_fract_z\n"
                "_atom_site_B_iso_or_equiv\n_atom_site_occupancy\n"
                + ''.join(s + "\n" for s in sites))

    def _el(r, el):
        return next((s for s in r.get('sites', []) if s.get('element') == el),
                    None) if r.get('success') else None

    _r17 = _batch_route(_fluorite(5.465, [('Nd3+', 3), ('U4+', 4.064), ('O2-', -2)],
        ['Nd1 Nd3+ 4 a 0 0 0 0.5 0.06', 'U1 U4+ 4 a 0 0 0 0.5 0.94',
         'O1 O2- 8 c 0.25 0.25 0.25 0.5 1.']), 'eir_v17.cif')
    _u, _nd = _el(_r17, 'U'), _el(_r17, 'Nd')
    report('17. a fractional valence on a shared site keeps its cation',
           _u is not None and _nd is not None and _u.get('bvs') is not None
           and abs(float(_u.get('valence')) - 4.064) < 1e-6,
           f"Nd0.06U0.94O2 as ICSD writes it ('U4+ 4.064'). Both species must "
           f"be summed, U at its fractional valence. Got U "
           f"{'missing' if _u is None else (_u.get('valence'), _u.get('bvs'))}, "
           f"Nd {'missing' if _nd is None else (_nd.get('valence'), _nd.get('bvs'))}")

    _r18 = _batch_route(_fluorite(5.468, [('U4+', 4.12), ('O2-', -2)],
        ['U1 U4+ 4 a 0 0 0 0.5 1.', 'O1 O2- 8 c 0.25 0.25 0.25 0.5 1.03']),
        'eir_v18.cif')
    _u18 = _el(_r18, 'U')
    report('18. a fractional valence as the only cation is assessed',
           bool(_r18.get('success')) and _u18 is not None
           and _u18.get('bvs') is not None,
           f"UO2.06 ('U4+ 4.12') failed in 2.0.42 as 'No M-X bonds found'. "
           f"Got success={_r18.get('success')}, error={_r18.get('error')}, "
           f"U bvs={_u18.get('bvs') if _u18 else None}")

    _r19 = _batch_route(_fluorite(5.6616, [('La3+', 3), ('Th5+', 5), ('O2-', -2)],
        ['La1 La3+ 4 a 0 0 0 0.5 0.5', 'Th1 Th5+ 4 a 0 0 0 0.5 0.5',
         'O1 O2- 8 c 0.25 0.25 0.25 0.5 1.']), 'eir_v19.cif')
    _th, _la = _el(_r19, 'Th'), _el(_r19, 'La')
    report('19. a valence with no parameters is reported, not removed',
           _th is not None and _la is not None and _th.get('bvs') is None,
           f"La0.5Th0.5O2 with Th5+, as ICSD balances it. Th must keep its "
           f"site row with no sum (R1 later), not vanish and leave La summed "
           f"alone. Got Th {'missing' if _th is None else ('bvs', _th.get('bvs'))}, "
           f"La {'missing' if _la is None else ('bvs', _la.get('bvs'))}")

    # -- 20 to 23. v2.0.44 --------------------------------------------------
    # All three go by the batch route, which is the one that hands the CIF's
    # own valences in, and each states the arithmetic it checks.
    # Origin choice 2, with the operations written out as ICSD does: the
    # IT number alone would be read at origin choice 1.
    _ops2 = [op.triplet() for op in
             gemmi.find_spacegroup_by_name('Fd-3m:2').operations()]

    def _pyrochlore(a, sites, types):
        return ("data_eir_validation_pyrochlore\n"
                f"_cell_length_a {a:.5f}\n_cell_length_b {a:.5f}\n"
                f"_cell_length_c {a:.5f}\n_cell_angle_alpha 90.\n"
                "_cell_angle_beta 90.\n_cell_angle_gamma 90.\n"
                "_space_group_name_H-M_alt 'F d -3 m Z'\n"
                "_space_group_IT_number 227\n"
                "loop_\n_space_group_symop_id\n_space_group_symop_operation_xyz\n"
                + ''.join(f"{i + 1} '{t}'\n" for i, t in enumerate(_ops2))
                + "loop_\n_atom_type_symbol\n_atom_type_oxidation_number\n"
                + ''.join(f"{t} {v}\n" for t, v in types)
                + "loop_\n_atom_site_label\n_atom_site_type_symbol\n"
                "_atom_site_symmetry_multiplicity\n_atom_site_Wyckoff_symbol\n"
                "_atom_site_fract_x\n_atom_site_fract_y\n_atom_site_fract_z\n"
                "_atom_site_B_iso_or_equiv\n_atom_site_occupancy\n"
                + ''.join(s + "\n" for s in sites))

    def _rows(r, el):
        return [s for s in (r.get('sites') or []) if s.get('element') == el]

    # 20. O and F sharing the anion position of a fluorite. Pr is summed over
    #     eight positions, each half O and half F with its own parameters,
    #     whichever species the CIF lists first.
    _a20 = 5.668
    _d20 = _a20 * math.sqrt(3) / 4
    _ro, _bo = get_bv_parameters_fractional('Pr', 3, 'O')
    _rf, _bf = get_bv_parameters_fractional('Pr', 3, 'F')
    _want20 = 8 * (0.5 * math.exp((_ro - _d20) / _bo)
                   + 0.5 * math.exp((_rf - _d20) / _bf))
    _got20 = []
    for _order in (('O1 O2- 8 c 0.25 0.25 0.25 0.5 0.5',
                    'F1 F1- 8 c 0.25 0.25 0.25 0.5 0.5'),
                   ('F1 F1- 8 c 0.25 0.25 0.25 0.5 0.5',
                    'O1 O2- 8 c 0.25 0.25 0.25 0.5 0.5')):
        _r20 = _batch_route(_fluorite(
            _a20, [('Pr3+', 3), ('O2-', -2), ('F1-', -1)],
            ['Pr1 Pr3+ 4 a 0 0 0 0.5 1.'] + list(_order)), 'eir_v20.cif')
        _p20 = _el(_r20, 'Pr')
        _got20.append((_p20.get('bvs'), _p20.get('cn'),
                       _p20.get('cn_occupancy_weighted')) if _p20 else None)
    report('20. a shared O/F position is summed over both species',
           all(g is not None and g[0] is not None
               and abs(g[0] - _want20) < 2e-3 and g[1] == 8
               and abs(float(g[2]) - 8.0) < 1e-3 for g in _got20),
           f"PrOF, a = {_a20} A, Pr-X {_d20:.4f} A. Want {_want20:.4f} v.u. "
           f"at CN 8 with either order; got (bvs, cn, cn_occ) = {_got20}")

    # 21. One element at two valences on two positions (ICSD 89934 pattern):
    #     Mn2+ shares A with La, Mn3+ shares B with Sb5+. Each species must be
    #     summed with the parameters of the valence its row reports. The B
    #     octahedron is regular, so its sum is 6 s(d) for the shortest bond.
    _r21 = _batch_route(_pyrochlore(10.30, [
        'La1 La3+ 16 c 0 0 0 0.5 0.5', 'Mn1 Mn2+ 16 c 0 0 0 0.5 0.5',
        'Mn2 Mn3+ 16 d 0.5 0.5 0.5 0.5 0.25', 'Sb1 Sb5+ 16 d 0.5 0.5 0.5 0.5 0.75',
        'O1 O2- 8 a 0.125 0.125 0.125 0.5 1.', 'O2 O2- 48 f 0.426 0.125 0.125 0.5 1.'],
        [('La3+', 3), ('Mn2+', 2), ('Mn3+', 3), ('Sb5+', 5), ('O2-', -2)]),
        'eir_v21.cif')
    _ok21, _det21 = bool(_r21.get('success')), []
    _sb = [s for s in _rows(_r21, 'Sb')]
    _dB = _sb[0].get('min_bond_length') if _sb else None
    for _s in (_r21.get('sites') or []):
        if _s.get('valence') is None or _s.get('bvs') is None:
            continue
        _same = abs(abs(float(_s.get('bvs_valence') or 0))
                    - abs(float(_s['valence']))) < 1e-6
        _ok21 = _ok21 and _same
        _det21.append(f"{_s.get('site_label')} {_s.get('bvs_valence')}->"
                      f"{_s['valence']}")
    if _dB:
        for _lab, _el21, _v21 in (('Mn2', 'Mn', 3), ('Sb1', 'Sb', 5)):
            _s21 = next((s for s in _r21.get('sites') or []
                         if s.get('site_label') == _lab), None)
            _r0, _b0 = get_bv_parameters_fractional(_el21, _v21, 'O')
            _w = 6 * math.exp((_r0 - _dB) / _b0)
            _ok21 = _ok21 and _s21 is not None and abs(_s21['bvs'] - _w) < 2e-3
            _det21.append(f"{_lab} {(_s21 or {}).get('bvs')} want {_w:.4f}")
    else:
        _ok21 = False
    report('21. each position is summed at the valence it reports', _ok21,
           f"Mn at 2+ and 3+ in one file used to fall to the database (Mn2+, "
           f"Sb3+) for every site. Got {'; '.join(_det21)}")

    # 22. Os(5+) on the pyrochlore B site (ICSD 155761, Cd2Os2O7). Six bonds,
    #     then six second-sphere oxygens at 3.72 A that Os(5+)'s soft b keeps
    #     above the cut-off. The shell must stop at six, the sum must be the
    #     octahedron's, and the anion side must not count the long contacts.
    _r22 = _batch_route(_pyrochlore(10.16043, [
        'Cd1 Cd2+ 16 d 0.5 0.5 0.5 0.5 1.', 'Os1 Os5+ 16 c 0 0 0 0.5 1.',
        'O1 O2- 48 f 0.32078 0.125 0.125 0.5 1.', 'O2 O2- 8 b 0.375 0.375 0.375 0.5 1.'],
        [('Cd2+', 2), ('Os5+', 5), ('O2-', -2)]), 'eir_v22.cif')
    _os = _el(_r22, 'Os')
    _r0o, _b0o = get_bv_parameters_fractional('Os', 5, 'O')
    _want22 = (6 * math.exp((_r0o - _os['min_bond_length']) / _b0o)
               if _os and _os.get('min_bond_length') else None)
    _o48 = next((a for a in (_r22.get('anion_sites') or [])
                 if a.get('anion_label') == 'O1'), {})
    report('22. a shell stops at the void before the second sphere',
           _os is not None and _os.get('cn') == 6
           and _os.get('cn_before_void_guard') == 12 and _want22 is not None
           and abs(_os['bvs'] - _want22) < 2e-3
           and str(_o48.get('anion_ligands')) in ('Cd:2,Os:2', 'Os:2,Cd:2'),
           f"Os CN {_os.get('cn') if _os else None} (before the guard "
           f"{_os.get('cn_before_void_guard') if _os else None}), bvs "
           f"{_os.get('bvs') if _os else None} want "
           f"{_want22 if _want22 is None else round(_want22, 4)}; O1 ligands "
           f"{_o48.get('anion_ligands')}")

    # 23. One element at two valences on ONE position (ICSD 79391, Tl2Nb2O7:
    #     Tl1+ and Tl3+ half each). Each label is summed with its own
    #     valence's parameters; their mean, Tl2+, has none. The index is the
    #     RMS over the two labels of their own deviations.
    _a23 = 5.60
    _d23 = _a23 * math.sqrt(3) / 4
    _r1, _b1 = get_bv_parameters_fractional('Tl', 1, 'O')
    _r3, _b3 = get_bv_parameters_fractional('Tl', 3, 'O')
    _w1 = 8 * math.exp((_r1 - _d23) / _b1)
    _w3 = 8 * math.exp((_r3 - _d23) / _b3)
    _wg = math.sqrt(((_w1 - 1) ** 2 + (_w3 - 3) ** 2) / 2)
    _r23 = _batch_route(_fluorite(_a23, [('Tl1+', 1), ('Tl3+', 3), ('O2-', -2)],
        ['Tl1 Tl1+ 4 a 0 0 0 0.5 0.5', 'Tl2 Tl3+ 4 a 0 0 0 0.5 0.5',
         'O1 O2- 8 c 0.25 0.25 0.25 0.5 1.']), 'eir_v23.cif')
    _t1 = next((s for s in _r23.get('sites') or [] if s.get('site_label') == 'Tl1'), {})
    _t3 = next((s for s in _r23.get('sites') or [] if s.get('site_label') == 'Tl2'), {})
    report('23. one element at two valences on one position, each its own sum',
           _t1.get('bvs') is not None and _t3.get('bvs') is not None
           and abs(_t1['bvs'] - _w1) < 2e-3 and abs(_t3['bvs'] - _w3) < 2e-3
           and _r23.get('gii') is not None and abs(_r23['gii'] - _wg) < 2e-3,
           f"Tl1+ want {_w1:.4f} got {_t1.get('bvs')}; Tl3+ want {_w3:.4f} got "
           f"{_t3.get('bvs')}; GII want {_wg:.4f} got {_r23.get('gii')}")

    # -- 24. v2.0.45: the continuous shape measure ---------------------------
    # Two published distances between reference shapes (octahedron to the
    # equal-edged trigonal prism 16.737; tetrahedron to square 33.333), zero
    # for a regular octahedron, and one strongly distorted octahedron: the
    # pyrochlore B site at x = 0.38 (origin 2, B on 16c; a = 10.4618 A, the
    # cell of ICSD 253760), where 2.0.44's iteration stopped at 81.5. The same
    # site, turned and with its ligands listed in other orders, must give one
    # value.
    def _pyroB(x, a):
        _pts = set()
        for _op in gemmi.find_spacegroup_by_name('Fd-3m:2').operations():
            _f = _op.apply_to_xyz([x, 0.125, 0.125])
            for _d in itertools.product((-1, 0, 1), repeat=3):
                _pts.add(tuple(round((_f[i] % 1) + _d[i], 6) for i in range(3)))
        return [np.array(p) * a for p in sorted(_pts)
                if np.linalg.norm(np.array(p) * a) < 2.3]
    _o0 = (0.0, 0.0, 0.0)
    _tpr = _CSHM_REFERENCE['trigonal prismatic'][1]
    _tet = _CSHM_REFERENCE['tetrahedral'][1]
    _sq = _CSHM_REFERENCE['square planar'][1]
    _s_oc_tpr = cshm(_o0, _tpr, 'octahedral')
    _s_tpr_oc = cshm(_o0, _CSHM_REFERENCE['octahedral'][1], 'trigonal prismatic')
    _s_t_sp = cshm(_o0, _sq, 'tetrahedral')
    _s_sp_t = cshm(_o0, _tet, 'square planar')
    _reg = _pyroB(0.3125, 10.4618)
    _s_reg = cshm(_o0, _reg, 'octahedral') if len(_reg) == 6 else None
    _dis = _pyroB(0.38, 10.4618)
    _vals = []
    if len(_dis) == 6:
        _rng = np.random.default_rng(2045)
        for _k in range(6):
            _ax = _rng.normal(size=3)
            _ax /= np.linalg.norm(_ax)
            _th = _rng.uniform(0, np.pi)
            _K = np.array([[0, -_ax[2], _ax[1]], [_ax[2], 0, -_ax[0]],
                           [-_ax[1], _ax[0], 0]])
            _R = np.eye(3) + np.sin(_th) * _K + (1 - np.cos(_th)) * _K @ _K
            if _k == 0:
                _R = np.eye(3)
            _order = _rng.permutation(6) if _k else np.arange(6)
            _vals.append(cshm(_o0, [_R @ _dis[i] for i in _order], 'octahedral'))
    _ok24 = (None not in (_s_oc_tpr, _s_tpr_oc, _s_t_sp, _s_sp_t, _s_reg)
             and abs(_s_oc_tpr - 16.737) < 1e-3 and abs(_s_tpr_oc - 16.737) < 1e-3
             and abs(_s_t_sp - 100 / 3) < 1e-6 and abs(_s_sp_t - 100 / 3) < 1e-6
             and abs(_s_reg) < 1e-9 and len(_vals) == 6 and None not in _vals
             and max(_vals) - min(_vals) < 1e-9 and 5 < _vals[0] < 12)
    report('24. continuous shape measure: published values, exact search',
           _ok24,
           f"OC-6 to TPR-6 {_s_oc_tpr} and back {_s_tpr_oc} (want 16.737); "
           f"T-4 to SP-4 {_s_t_sp} and back {_s_sp_t} (want 33.333); regular "
           f"octahedron {_s_reg}; pyrochlore B site at x = 0.38 in six "
           f"orientations and orders {[None if v is None else round(v, 6) for v in _vals]}")

    if verbose:
        print()
        print("=" * 70)
        n_pass = sum(results)
        if all(results):
            print(f"  ALL {len(results)} TESTS PASSED")
        else:
            print(f"  {n_pass} of {len(results)} passed - "
                  f"{len(results)-n_pass} FAILED")
        print("=" * 70)
    if not all(results):
        # v2.0.13: a failing suite RAISES. It used to return False with
        # nothing reading the value, so a broken pipeline printed FAIL and
        # then ran the batch anyway and reported numbers.
        _failed = [i + 1 for i, x in enumerate(results) if not x]
        raise AssertionError(
            f'Eir validation FAILED: test(s) {_failed} of {len(results)}. '
            f'Re-run VALIDATE(verbose=True) for the detail.')
    return True


# VALIDATE()   # eir package: run by eir.validate()


# ---------------------------------------------------------------------------
# v2.0.15, item 4.7: Fd-3m:S against Fd-3m:Z.
#
# Lives here rather than in CELL 1c because normaliser_translations and
# origin_choice_offset are defined in CELL 2, below that cell.
#
# The open question was whether the two origin settings of Fd-3m give the same
# normaliser output. They do. Both return [(0.5, 0.5, 0.5)] and nothing else,
# and origin_choice_offset returns (3/8, 3/8, 3/8) from either. The cache is
# keyed on xhm(), which carries the :1 / :2 suffix, so the two never collide.
#
# The thing that DID need checking is the naming. ICSD writes the origin choice
# as a trailing S or Z - 'F d -3 m S', 'F d -3 m Z' - and gemmi does not
# recognise either as a space group name: find_spacegroup_by_name returns None
# for both. Read on 522 real ICSD files, Eir resolves them correctly anyway,
# S to :1 and Z to :2, 366 and 146 of them respectively, plus I 41/a m d S and
# Z. So the S/Z convention is handled, but by a route that nothing was testing.
# It is tested here now, because it is one silent regression away from reading
# every Z-setting spinel on origin-choice-1 operations.
def VALIDATE_SETTINGS(verbose=True):
    """Assert that the two Fd-3m settings agree, and that S/Z are handled."""
    results = []

    def report(name, ok, detail=''):
        results.append(bool(ok))
        if verbose:
            print(f"  {'pass' if ok else 'FAIL'}  {name}"
                  + (f"   {detail}" if detail else ''))

    if verbose:
        print("\nFd-3m SETTING CHECK (item 4.7)")

    s1 = gemmi.find_spacegroup_by_name('Fd-3m:1')
    s2 = gemmi.find_spacegroup_by_name('Fd-3m:2')
    report('1. both Fd-3m settings resolve', s1 is not None and s2 is not None)
    if s1 is None or s2 is None:
        return False

    t1, t2 = normaliser_translations(s1), normaliser_translations(s2)
    report('2. normaliser output is setting-independent', t1 == t2,
           f'{t1} against {t2}')
    report('3. and is the cubic half-lattice vector alone',
           t1 == [(0.5, 0.5, 0.5)], str(t1))
    report('4. the two settings are distinct groups', s1.xhm() != s2.xhm(),
           f'{s1.xhm()} against {s2.xhm()}')
    o1, o2 = origin_choice_offset(s1), origin_choice_offset(s2)
    report('5. origin offset agrees from either setting', o1 == o2, str(o1))

    # The ICSD convention. If gemmi ever starts accepting these, the CIF
    # cleaner's translation must still be right, so assert the CURRENT state
    # rather than the desired one and let the test fail loudly if it moves.
    sS = gemmi.find_spacegroup_by_name('Fd-3m:S')
    sZ = gemmi.find_spacegroup_by_name('Fd-3m:Z')
    report('6. gemmi does not know the ICSD S/Z names, so Eir must translate',
           sS is None and sZ is None)

    ok = all(results)
    print(f"  {'ALL SETTING TESTS PASSED' if ok else 'SOMETHING FAILED'}"
          f"  ({sum(results)}/{len(results)})")
    if not ok:
        raise AssertionError(
            'Fd-3m setting check failed. A test whose failure has no '
            'consequence is not a test.')
    return ok


# VALIDATE_SETTINGS()   # eir package: run by eir.validate()
